"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { Menu, X, ChevronDown, ChevronUp, Search } from "lucide-react"; 
import { UserCircleIcon, BriefcaseIcon, CodeIcon, PaintBrushIcon } from '@heroicons/react/24/outline';

const Navbar = () => {
  const router = useRouter();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [openDropdown, setOpenDropdown] = useState<string | null>(null);

  const toggleDropdown = (itemName: string) => {
    setOpenDropdown(openDropdown === itemName ? null : itemName);
  };

  return (
    <nav className="fixed top-0 left-0 w-full bg-gray-900 bg-opacity-90 text-white shadow-md z-50">
      <div className="flex items-center justify-between px-6 py-4">
        {/* Logo */}
        <div className="text-2xl font-bold cursor-pointer" onClick={() => router.push("/")}>
          AVACASA
        </div>

        {/* Search Bar */}
        <div className="hidden md:flex items-center bg-gray-800 px-3 py-1 rounded-full">
          <Search className="w-5 h-5 text-gray-400" />
          <input
            type="text"
            placeholder="Search..."
            className="bg-transparent text-white placeholder-gray-400 ml-2 outline-none"
          />
        </div>

        {/* Desktop Menu */}
        <div className="hidden lg:flex items-center space-x-10">
          <a href="/" className="hover:text-blue-400 transition">🏠 Home</a>
          <a href="/about" className="hover:text-blue-400 transition">📖 About Us</a>
          
          {/* Services Dropdown */}
          <div className="relative">
            <button className="hover:text-blue-400 flex items-center" onClick={() => toggleDropdown("services")}>
              🛠️ Services {openDropdown === "services" ? <ChevronUp className="ml-1" /> : <ChevronDown className="ml-1" />}
            </button>
            {openDropdown === "services" && (
              <div className="absolute mt-2 w-52 bg-gray-800 text-white shadow-lg rounded-lg p-2">
                <a href="/services/web-development" className="block px-4 py-2 hover:bg-gray-700 flex items-center">
                  <CodeIcon className="w-5 h-5 mr-2" /> Web Development
                </a>
                <a href="/services/ui-ux" className="block px-4 py-2 hover:bg-gray-700 flex items-center">
                  <PaintBrushIcon className="w-5 h-5 mr-2" /> UI/UX Design
                </a>
                <a href="/services/marketing" className="block px-4 py-2 hover:bg-gray-700 flex items-center">
                  <BriefcaseIcon className="w-5 h-5 mr-2" /> Digital Marketing
                </a>
              </div>
            )}
          </div>

          <a href="/blog" className="hover:text-blue-400 transition">📝 Blog</a>
          <a href="/contact" className="hover:text-blue-400 transition">📩 Contact</a>
        </div>

        {/* Get Started Button */}
        <button 
          onClick={() => router.push('/login')}
          className="hidden md:flex items-center bg-blue-600 px-4 py-2 rounded-full hover:bg-blue-500 transition"
        >
          <UserCircleIcon className="w-6 h-6 mr-2" /> Get Started
        </button>

        {/* Mobile Menu Toggle */}
        <button className="lg:hidden" onClick={() => setIsMenuOpen(true)}>
          <Menu className="w-6 h-6" />
        </button>
      </div>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="fixed top-0 left-0 w-full h-full bg-gray-900 text-white flex flex-col p-6 z-50">
          <div className="flex justify-between items-center">
            <div className="text-xl font-bold">AVACASA</div>
            <X className="w-6 h-6 cursor-pointer" onClick={() => setIsMenuOpen(false)} />
          </div>

          <div className="flex-grow mt-6">
            <a href="/" className="block text-lg hover:text-blue-400 mb-4">🏠 Home</a>
            <a href="/about" className="block text-lg hover:text-blue-400">📖 About Us</a>
            <a href="/services" className="block text-lg hover:text-blue-400 mt-4">🛠️ Services</a>
            <a href="/blog" className="block text-lg hover:text-blue-400 mt-4">📝 Blog</a>
            <a href="/contact" className="block text-lg hover:text-blue-400 mt-4">📩 Contact</a>
          </div>

          <button 
            onClick={() => router.push('/login')}
            className="bg-blue-600 px-4 py-2 rounded-full hover:bg-blue-500 transition mt-6"
          >
            Get Started
          </button>
        </div>
      )}
    </nav>
  );
};

export default Navbar;