"use client";

const PrimaryButton = ({ text, onClick }: { text: string; onClick?: () => void }) => {
  return (
    <button
      onClick={onClick}
      className="px-6 py-2 bg-blue-600 text-white font-semibold rounded-full hover:bg-blue-700 transition duration-300 shadow-md"
    >
      {text}
    </button>
  );
};

export default PrimaryButton;
